Az alábbi egyetlen forrásfájl a Zig standard könyvtár dokumentált `std.http.Client` kérésfolyamára — `request`, `start`, `writeAll`, `finish`, `wait`, `read` — és a `std.json.parseFromSlice` JSON-feldolgozására épül, ezért valódi streamelt HTTP POST kliensként van megírva egy fájlban.[1][2]

```zig
const std = @import("std");

const AppError = error{
    MissingKey,
    RequestFailed,
    ApiError,
    UnexpectedJsonShape,
};

const Io = struct {
    stdout: std.fs.File.Writer,
    stderr: std.fs.File.Writer,
};

const request_body =
    \\{
    \\  "messages": [
    \\    {
    \\      "role": "system",
    \\      "content": ""
    \\    },
    \\    {
    \\      "role": "user",
    \\      "content": [
    \\        {
    \\          "type": "image_url",
    \\          "image_url": {
    \\            "url": "data:image/jpeg;base64,<base64-encoded-image>"
    \\          }
    \\        }
    \\      ]
    \\    }
    \\  ],
    \\  "model": "gemma-4-31b",
    \\  "stream": true,
    \\  "max_completion_tokens": 40000,
    \\  "temperature": 0,
    \\  "top_p": 0.95
    \\}
;

fn startsWithBytes(bytes: []const u8, prefix: []const u8) bool {
    if (prefix.len > bytes.len) return false;

    var i: usize = 0;
    while (i < prefix.len) : (i += 1) {
        if (bytes[i] != prefix[i]) return false;
    }
    return true;
}

fn bytesStrictEqual(a: []const u8, b: []const u8) bool {
    if (a.len != b.len) return false;

    var i: usize = 0;
    while (i < a.len) : (i += 1) {
        if (a[i] != b[i]) return false;
    }
    return true;
}

fn findFirstByteFrom(bytes: []const u8, needle: u8, start: usize) ?usize {
    if (start >= bytes.len) return null;

    var i: usize = start;
    while (i < bytes.len) : (i += 1) {
        if (bytes[i] == needle) return i;
    }
    return null;
}

fn writeJsonValue(writer: anytype, value: std.json.Value) !void {
    try std.json.stringify(value, .{}, writer);
}

fn processEventJson(allocator: std.mem.Allocator, io: *Io, data_payload: []const u8) !bool {
    if (bytesStrictEqual(data_payload, "[DONE]")) {
        return true;
    }

    if (data_payload.len == 0) {
        return false;
    }

    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, data_payload, .{});
    defer parsed.deinit();

    const root = switch (parsed.value) {
        .object => |obj| obj,
        else => return AppError.UnexpectedJsonShape,
    };

    if (root.get("error")) |error_value| {
        try io.stderr.writeAll("Cerebras API error: ");

        switch (error_value) {
            .object => |error_obj| {
                if (error_obj.get("message")) |message_value| {
                    switch (message_value) {
                        .string => |message| try io.stderr.writeAll(message),
                        else => try writeJsonValue(io.stderr, message_value),
                    }
                } else {
                    try writeJsonValue(io.stderr, error_value);
                }
            },
            else => try writeJsonValue(io.stderr, error_value),
        }

        try io.stderr.writeByte('\n');
        return AppError.ApiError;
    }

    const choices_value = root.get("choices") orelse return false;
    const choices = switch (choices_value) {
        .array => |arr| arr,
        else => return AppError.UnexpectedJsonShape,
    };

    if (choices.items.len == 0) {
        return false;
    }

    const first_choice = switch (choices.items[0]) {
        .object => |obj| obj,
        else => return AppError.UnexpectedJsonShape,
    };

    const delta_value = first_choice.get("delta") orelse return false;
    const delta = switch (delta_value) {
        .object => |obj| obj,
        else => return AppError.UnexpectedJsonShape,
    };

    const content_value = delta.get("content") orelse return false;
    const content = switch (content_value) {
        .string => |s| s,
        else => return AppError.UnexpectedJsonShape,
    };

    if (content.len != 0) {
        try io.stdout.writeAll(content);
    }

    return false;
}

fn consumeSseLine(
    event_data: *std.ArrayList(u8),
    allocator: std.mem.Allocator,
    io: *Io,
    raw_line: []const u8,
) !bool {
    var line = raw_line;

    if (line.len > 0 and line[line.len - 1] == '\r') {
        line = line[0 .. line.len - 1];
    }

    if (line.len == 0) {
        const done = try processEventJson(allocator, io, event_data.items);
        event_data.items.len = 0;
        return done;
    }

    if (line[0] == ':') {
        return false;
    }

    if (startsWithBytes(line, "data:")) {
        var value = line["data:".len..];

        if (value.len > 0 and value[0] == ' ') {
            value = value[1..];
        }

        if (event_data.items.len != 0) {
            try event_data.append('\n');
        }

        try event_data.appendSlice(value);
    }

    return false;
}

fn writeErrorResponse(req: *std.http.Client.Request, io: *Io) !void {
    var buffer: [8192]u8 = undefined;

    while (true) {
        const n = try req.read(buffer[0..]);
        if (n == 0) break;
        try io.stderr.writeAll(buffer[0..n]);
    }

    try io.stderr.writeByte('\n');
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();

    const allocator = gpa.allocator();

    var io = Io{
        .stdout = std.io.getStdOut().writer(),
        .stderr = std.io.getStdErr().writer(),
    };

    const api_key = std.process.getEnvVarOwned(allocator, "CEREBRAS_API_KEY") catch |err| switch (err) {
        error.EnvironmentVariableNotFound => {
            try io.stderr.writeAll("CEREBRAS_API_KEY environment variable is not set\n");
            return AppError.MissingKey;
        },
        else => return err,
    };
    defer allocator.free(api_key);

    if (api_key.len == 0) {
        try io.stderr.writeAll("CEREBRAS_API_KEY environment variable is empty\n");
        return AppError.MissingKey;
    }

    const authorization = try std.fmt.allocPrint(allocator, "Bearer {s}", .{api_key});
    defer allocator.free(authorization);

    var client = std.http.Client{
        .allocator = allocator,
    };
    defer client.deinit();

    var client_read_buffer: [65536]u8 = undefined;

    const uri = try std.Uri.parse("");

    var headers = std.http.Headers.init(allocator);
    defer headers.deinit();

    try headers.append("authorization", authorization);
    try headers.append("content-type", "application/json");
    try headers.append("accept-encoding", "identity");
    try headers.append("accept", "text/event-stream");

    var req = try client.request(.POST, uri, headers, .{
        .handle_redirects = false,
        .header_strategy = .{ .static = client_read_buffer[0..] },
    });
    defer req.deinit();

    req.transfer_encoding = .{ .content_length = request_body.len };

    try req.start();
    try req.writeAll(request_body);
    try req.finish();
    try req.wait();

    const status_code = @intFromEnum(req.response.status);
    if (status_code < 200 or status_code >= 300) {
        try io.stderr.print("Cerebras API request failed with HTTP status {d}\n", .{status_code});
        try writeErrorResponse(&req, &io);
        return AppError.RequestFailed;
    }

    var read_buffer: [16384]u8 = undefined;
    var pending = std.ArrayList(u8).init(allocator);
    defer pending.deinit();

    var event_data = std.ArrayList(u8).init(allocator);
    defer event_data.deinit();

    var done = false;

    while (!done) {
        const n = try req.read(read_buffer[0..]);
        if (n == 0) break;

        try pending.appendSlice(read_buffer[0..n]);

        var consumed: usize = 0;
        var search_from: usize = 0;

        while (findFirstByteFrom(pending.items, '\n', search_from)) |newline_index| {
            const line = pending.items[consumed..newline_index];
            done = try consumeSseLine(&event_data, allocator, &io, line);

            consumed = newline_index + 1;
            search_from = consumed;

            if (done) break;
        }

        if (consumed != 0) {
            const remaining = pending.items.len - consumed;

            var i: usize = 0;
            while (i < remaining) : (i += 1) {
                pending.items[i] = pending.items[consumed + i];
            }

            pending.items.len = remaining;
        }
    }

    if (!done and pending.items.len != 0) {
        done = try consumeSseLine(&event_data, allocator, &io, pending.items);
    }

    if (!done and event_data.items.len != 0) {
        _ = try processEventJson(allocator, &io, event_data.items);
    }
}
